import{_ as n,c as p,o as i,a1 as e}from"./chunks/framework.4TBoba-N.js";const s="/images/daily/gdg-daegu-build-with-ai-hackathon/logo.ico",t="/images/daily/gdg-daegu-build-with-ai-hackathon/img_7007.jpg",l="/images/daily/gdg-daegu-build-with-ai-hackathon/screenshot_135115.png",o="/images/daily/gdg-daegu-build-with-ai-hackathon/screenshot_135156.png",u="/images/daily/gdg-daegu-build-with-ai-hackathon/architecture.png",c="/images/daily/gdg-daegu-build-with-ai-hackathon/image.png",d="/images/daily/gdg-daegu-build-with-ai-hackathon/image_1.png",g="/images/daily/gdg-daegu-build-with-ai-hackathon/nametags.jpg",r="/images/daily/gdg-daegu-build-with-ai-hackathon/img_7015.jpg",D=JSON.parse('{"title":"[Daily] GDG Daegu Build With AI ハッカソンに参加してみました！","description":"GDG Daegu Build With AI ハッカソン参加記。Gymbroサービスの企画から実装までの過程を紹介。","frontmatter":{"title":"[Daily] GDG Daegu Build With AI ハッカソンに参加してみました！","description":"GDG Daegu Build With AI ハッカソン参加記。Gymbroサービスの企画から実装までの過程を紹介。","date":"2026-03-23T11:55:00.000Z","lang":"ja","categories":["Daily"],"tags":["GDG","Hackathon","AI","Gemini","MediaPipe"]},"headers":[],"relativePath":"post/daily-gdg-daegu-build-with-ai-hackathon/index.md","filePath":"posts/daily-gdg-daegu-build-with-ai-hackathon/index.md"}'),h={name:"post/daily-gdg-daegu-build-with-ai-hackathon/index.md"};function m(_,a,q,b,k,y){return i(),p("div",null,[...a[0]||(a[0]=[e('<h1 id="daily-gdg-daegu-build-with-ai-ハッカソンに参加してみました" tabindex="-1">[Daily] GDG Daegu Build With AI ハッカソンに参加してみました！ <a class="header-anchor" href="#daily-gdg-daegu-build-with-ai-ハッカソンに参加してみました" aria-label="Permalink to &quot;[Daily] GDG Daegu Build With AI ハッカソンに参加してみました！&quot;">​</a></h1><p>생성일: 2026년 3월 23일 오후 7:55</p><hr><p><img src="'+s+'" alt="GDGIcon.png"></p><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><hr><p>大邱で取材するGoogle Developer Groupでのハッカソンを参加しました！</p><p>AIでビルドをし、自分たちのサービスを作ろうと言う大会でした！</p><p>普段AIを使って開発はしていましたが、短期間でどのぐらい作れるかを試してみたかったので興味を持ちました！</p><p>なので自分はここで友達３人と一緒にチームを組んで大会に参加することになりました。</p><h2 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容&quot;">​</a></h2><hr><p>自分たちはまずアイディアをジムに通ってるユーザーをターゲットにトレーニングの面倒を見てくれるアプリケーションを企画しました。</p><p>まずこのアイディアーにした理由は二つです。</p><ol><li>初心者がジムで運動をする時、自分の姿勢があってるかわからない。</li><li>Youtubeで姿勢を見ても真似するのが難しい</li></ol><p>この二つの問題を発見し、これを土台として開発を進みました。</p><p>主に開発時間は２時間半で、サービスリリーズや、発表の準備までやる感じで進みました。</p><p><img src="'+t+'" alt="img_7007.jpg"></p><p>自分はここで社会社であり、開発者として役割を担当しました。</p><h3 id="アイディア確定過程" tabindex="-1">アイディア確定過程 <a class="header-anchor" href="#アイディア確定過程" aria-label="Permalink to &quot;アイディア確定過程&quot;">​</a></h3><hr><p>開発時間は 13:00 ~ 15:30までだったので、早めにアイディアを決めたかったです。</p><p>なので自分は 13:00 ~ 13:15まで開発に必要な</p><ol><li>サービスの目的</li><li>サービスの概要</li><li>ターゲットユーザー</li><li>必要な機能</li><li>あって欲しい機能</li></ol><p>などを決めました。</p><p>サービスの目的として、ジムに通ってる人たちのためにガイドラインの提供。</p><p>そして姿勢を矯正してくれる！のが自分たちのサービスの目的でした。</p><p>このサービスはジムに興味がある人たちが最初運動マシンを使いづらいと言ってくれる時が多く、自分の姿勢があっているかわからない時が多いという周りの言葉でこのようなサービスが必要だと判断しました。</p><p>なので自分たちはターゲットユーザーを運動初心者、老人、運動をやっていますが自分の姿勢があっているかわからないと言う人たちをターゲットにしました。</p><p>ここで必要な機能として、姿勢を把握できるAI、そして自分たちの姿勢を正しく判断できるのかの研究が必要でした。</p><p>姿勢を判断するためにはスキャン. つまり自分たちの姿勢をカメラで取り、それをAIに入れ込んでフィードバックを残せるよう機能を作ることが大事でした。</p><p>その後はログイン機能や、自分が残した記録に対してアクセスできるようMypageがあって欲しいという意見を交換しました。</p><h3 id="サービス内容" tabindex="-1">サービス内容 <a class="header-anchor" href="#サービス内容" aria-label="Permalink to &quot;サービス内容&quot;">​</a></h3><hr><p><img src="'+s+'" alt="logo.ico"></p><p>議論の結果、自分たちのサービスでGymbroと言う名前のサービスをリリーズすることに決まりました。</p><p>中で使っていた AI は Gemini AI や Media Pipe を使用しました。</p><p>実際にYoutubeで正しい姿勢の画像をとり、それをMedia Pipeに入れて人の骨格の画像を作りました。</p><p>これをプロムポートで記入し、この姿勢が正しいのかフィードバックを残して欲しいと言う研究を1時間を使ってしました。</p><p><img src="'+l+'" alt="screenshot_135115.png"></p><p><img src="'+o+`" alt="screenshot_135156.png"></p><p>[KR] 피지컬 갤러リ Youtube</p><blockquote><p>初期のプロムポート</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[System Role]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>あなたはウェイトトレーニング初心者のためのAI姿勢矯正コーチです。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ユーザーの目標は、正確なターゲット筋肉（胸）の刺激点を見つけ、誤った姿勢による肩の痛みを予防することです。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Task]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>添付された画像を分析して、ベンチプレス姿勢の問題点を把握してください。 特にMediaPipeが描いた白い骨格オーバーレイを参考にして、左右のバランス、肘の角度、肩甲骨の固定を評価してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Input Context]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>現在の画像はベンチプレスの最後のプレス（上げる）区間です。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Output Format (JSON)]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>必ず以下のJSON形式でのみ回答してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;posture_score&quot;: &quot;0~100の間のスコア&quot;,</span></span>
<span class="line"><span>  &quot;danger_level&quot;: &quot;Safe / Warning / Danger 중 택 1&quot;,</span></span>
<span class="line"><span>  &quot;ai_visual_analysis&quot;: &quot;画像と骨組みを通じて把握した視覚적特徴 (1文)&quot;,</span></span>
<span class="line"><span>  &quot;primary_issue&quot;: &quot;最も核心的な問題点 (1文)&quot;,</span></span>
<span class="line"><span>  &quot;feedback_message&quot;: &quot;初心者が即座に姿勢を修正できる具体的な行動指針（2〜3文）&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>結果プロムポート</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;posture_score&quot;: &quot;98&quot;,</span></span>
<span class="line"><span>  &quot;danger_level&quot;: &quot;Safe&quot;,</span></span>
<span class="line"><span>  &quot;ai_visual_analysis&quot;: &quot;白い骨格オーバーレイの分析結果、下降時の肘の角度が適切であり、特に上昇時にも肩関節のノードがベンチに固定され、肩甲骨の後降下設定が完璧に維持されています。&quot;</span></span>
<span class="line"><span>  &quot;primary_issue&quot;: &quot;大きな問題は見つかりませんでした。 初心者が目指すべき理想的な姿勢です。&quot;</span></span>
<span class="line"><span>  &quot;feedback_message&quot;: &quot;提示された正しい例は、ベンチプレスの教科書的な姿勢です。 肩甲骨のしっかりとした固定、適切な肘の角度、そして動作中ずっと維持される胸椎の伸展まで完璧です。 この姿勢を体に覚えさせ、毎セットこの感覚を再現しようと努力することが、胸の筋肉のターゲット刺激を見つけ、肩の痛みを予防する近道です。&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上のようにMedia Pipeで伝えといた写真の点数や、フィードバックをもらってユーザーに渡して画面に写せるようページを作る計画を立てました。</p><h3 id="ページ構成" tabindex="-1">ページ構成 <a class="header-anchor" href="#ページ構成" aria-label="Permalink to &quot;ページ構成&quot;">​</a></h3><hr><p>自分たちは主に下のようなアーキテクチャで作業する感じで進みました。</p><p><img src="`+u+'" alt="architecture.png"></p><p>自分はサーバーのプロジェクト構築や、フロントエンドの作業に入りました。</p><p>サーバーの方はバックエンドエンジニアを勉強している2人のチームメートがいたので、残っているフロントエンドをやりました。</p><p>１時間内でVercelへのリリーズや、Next.jsと画面スキャンをGemini AI と Antigravityを利用して作りました。</p><p>ここでGithub Organizationで開発を進めていましたが、OrganizationはVercel無料バージョンでリリーズができない理由があり、個人RepositoryへコードをコピーできるようGithub Action의 코드를書いて問題を解決しました。</p><p>したは自分が作ったページです！</p><p>ちなみに１時間だと書きましたが、Notion MCPを繋いでContextを記入すると一瞬でページを作ってくれるのがすごく不思議でした！</p><p><img src="'+c+'" alt="image.png"></p><p><img src="'+d+'" alt="image_1.png"></p><p><img src="'+g+'" alt="nametags.jpg"></p><h2 id="結果-感想" tabindex="-1">結果 &amp; 感想 <a class="header-anchor" href="#結果-感想" aria-label="Permalink to &quot;結果 &amp; 感想&quot;">​</a></h2><hr><p>結果として、自分たちは立証はできなかったんですが、貴重な時間を使ってこんな短時間で未熟ですが、結果物を出したことに対してすごく喜べる時間でした！</p><p><img src="'+r+'" alt="img_7015.jpg"></p><p>実際に発表とともに作品に対して説明ができる環境が作られたのがすごく嬉しかったのと、チームプロジェクトをうまく進んだことに意味をおきたかったのでポストで残しておこうと思います！</p><p>またAIがどんどん作業を人より細かくできると言うことにこれから開発者という職群は消え、企画者として活躍ができるのではないかを考える時間を持つことができました！</p><p>以上で2026年のGDG活動ポストでした！</p>',67)])])}const A=n(h,[["render",m]]);export{D as __pageData,A as default};
